// Package ids generates and parses prefixed UUIDv7 identifiers
// (for example pi_..., re_...).
//
// ADR 0001 §6: a public ID is a type prefix plus an opaque, URL-safe suffix
// generated by the server. The suffix is a UUIDv7 written as 32 lowercase hex
// digits (no dashes), so IDs of one type sort by creation time. Clients must
// treat the suffix as opaque.
package ids

import (
	"crypto/rand"
	"encoding/binary"
	"encoding/hex"
	"errors"
	"fmt"
	"strings"
	"time"
)

// Prefix is a resource type prefix, including the trailing underscore.
type Prefix string

// Prefixes fixed by ADR 0001 §6. Others are added when their resource is
// first built (OPEN_QUESTIONS Q10, Q15).
const (
	PaymentIntent Prefix = "pi_"
	Operation     Prefix = "op_"
	Refund        Prefix = "re_"
	Merchant      Prefix = "mer_"
)

const suffixLen = 32

// ErrInvalid is returned for an ID that is malformed or has the wrong prefix.
var ErrInvalid = errors.New("invalid identifier")

// Generator creates IDs. Now supplies the timestamp (injectable for tests);
// when nil, the system clock is used.
type Generator struct {
	Now func() time.Time
}

// New returns a fresh ID with prefix p using the system clock.
func New(p Prefix) string { return Generator{}.New(p) }

// New returns a fresh ID with prefix p.
func (g Generator) New(p Prefix) string {
	u := g.UUIDv7()
	return string(p) + hex.EncodeToString(u[:])
}

// UUIDv7 returns a random RFC 9562 version 7 UUID.
func (g Generator) UUIDv7() [16]byte {
	now := time.Now
	if g.Now != nil {
		now = g.Now
	}
	var u [16]byte
	if _, err := rand.Read(u[6:]); err != nil {
		// crypto/rand never fails on supported platforms (Go 1.24+ panics internally).
		panic(fmt.Sprintf("ids: crypto/rand: %v", err))
	}
	ms := uint64(now().UnixMilli()) //nolint:gosec // G115: Unix milliseconds are positive for any date this system will see.
	var ts [8]byte
	binary.BigEndian.PutUint64(ts[:], ms<<16)
	copy(u[0:6], ts[0:6])
	u[6] = (u[6] & 0x0f) | 0x70 // version 7
	u[8] = (u[8] & 0x3f) | 0x80 // RFC 9562 variant
	return u
}

// NewEventID returns a UUIDv7 in canonical 8-4-4-4-12 form, as CloudEvents
// event IDs use (04-06 §3.1).
func (g Generator) NewEventID() string {
	u := g.UUIDv7()
	h := hex.EncodeToString(u[:])
	return h[0:8] + "-" + h[8:12] + "-" + h[12:16] + "-" + h[16:20] + "-" + h[20:32]
}

// Parse checks that id has prefix p and a well-formed UUIDv7 suffix.
// It returns the ID unchanged when valid.
func Parse(p Prefix, id string) (string, error) {
	suffix, ok := strings.CutPrefix(id, string(p))
	if !ok || len(suffix) != suffixLen {
		return "", fmt.Errorf("%w: want %s<%d hex>", ErrInvalid, p, suffixLen)
	}
	b, err := hex.DecodeString(suffix)
	if err != nil || strings.ToLower(suffix) != suffix {
		return "", fmt.Errorf("%w: suffix must be lowercase hex", ErrInvalid)
	}
	if b[6]>>4 != 7 || b[8]>>6 != 2 {
		return "", fmt.Errorf("%w: suffix is not a UUIDv7", ErrInvalid)
	}
	return id, nil
}
